"""Generates out/w4-B.workflow.json (Brief A + Brief B, up to three products)."""
import json, pathlib

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1/"
OUT = pathlib.Path(__file__).resolve().parent / "w4-B.workflow.json"


def api_tool(name, desc, fields, required, max_retries=0, pre="", post="", mapping=None, baked=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    for f, spec in fields.items():
        s = dict(spec)
        s.setdefault("default", "{{" + f + "}}")
        props[f] = s
    for f, v in (baked or {}).items():
        props[f] = {"type": "string", "default": v}
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": max_retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + name},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "required": required, "properties": props},
            }},
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


def code_exec(code):
    assert "{{" not in code and "}}" not in code, "braces in code"
    return {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": code},
                "timeout_ms": {"type": "number", "default": 10000}}}}}


def nobrace(code):
    assert "{{" not in code and "}}" not in code, code
    return code


def grp(*conds):
    return {"logic": "or", "conditions": list(conds)}


def eq(var, val):
    return {"variable": var, "operator": "equals", "operand": val}


def gt(var, val):
    return {"variable": var, "operator": "greater_than", "operand": val}


def is_true(var):
    return [eq(var, "true"), eq(var, "True")]


ALWAYS = {"operator": "always"}

# ---------------------------------------------------------------- hooks (ledger kept in vars)
LEDGER_PRE = nobrace(r'''
try:
    import json as _j
    _b = config.get('body') if isinstance(config, dict) else None
    if isinstance(_b, dict):
        vars['_pending___TOOL__'] = _j.dumps(dict((k, _b.get(k)) for k in ('product_id', 'reason', 'queue', 'amount', 'date')))
except Exception:
    pass
''')

LEDGER_POST = nobrace(r'''
try:
    import json as _j
    _t = '__TOOL__'
    _ok = False
    if isinstance(result, dict):
        _d = result.get('data')
        try:
            _sc = int(result.get('status_code') or 0)
        except Exception:
            _sc = 0
        if isinstance(_d, dict) and _d.get('ok') in (True, 'true', 'True') and _sc < 400:
            _ok = True
    if _ok:
        try:
            _p = _j.loads(vars.get('_pending_' + _t) or '[]')
        except Exception:
            _p = dict()
        if not isinstance(_p, dict):
            _p = dict()
        for _k in ('product_id', 'reason', 'queue'):
            if not _p.get(_k):
                _p[_k] = vars.get(_t + '_args.' + _k)
        if _t == 'create_promise':
            vars['ledger_promises'] = str(int(vars.get('ledger_promises') or 0) + 1)
        elif _t == 'add_note':
            try:
                _n = _j.loads(vars.get('ledger_notes') or '[]')
            except Exception:
                _n = []
            _n.append([str(_p.get('product_id') or ''), str(_p.get('reason') or '')])
            vars['ledger_notes'] = _j.dumps(_n)
        elif _t == 'transfer_to_agent':
            vars['ledger_transfer'] = str(_p.get('queue') or 'general')
except Exception:
    pass
''')

CLOSE_PRE = nobrace(r'''
try:
    import json as _j
    _b = config.get('body') if isinstance(config, dict) else None
    if isinstance(_b, dict):
        _tq = str(vars.get('ledger_transfer') or '')
        try:
            _pc = int(vars.get('ledger_promises') or 0)
        except Exception:
            _pc = 0
        try:
            _notes = _j.loads(vars.get('ledger_notes') or '[]')
        except Exception:
            _notes = []
        try:
            _order = _j.loads(vars.get('product_order') or '[]')
        except Exception:
            _order = []
        _map = dict(restructuring='restructuring', support='support', general='human')
        if _tq:
            _b['outcome'] = 'transferred'
            _b['reason'] = _map.get(_tq, 'human')
        elif _pc > 0:
            _b['outcome'] = 'promise'
        elif _notes:
            _first = dict()
            for _n in _notes:
                if isinstance(_n, list) and len(_n) == 2 and _n[0] not in _first:
                    _first[_n[0]] = _n[1]
            _rs = [_first[p] for p in _order if p in _first] or list(_first.values())
            if _rs and all(r == 'paid' for r in _rs):
                _b['outcome'] = 'paid'
            elif _rs:
                _b['outcome'] = 'no_promise'
                _b['reason'] = [r for r in _rs if r != 'paid'][0]
        _r = _b.get('reason')
        if _b.get('outcome') in ('promise', 'paid') or _r is None or '{' in str(_r) or str(_r).strip() == '':
            _b.pop('reason', None)
except Exception:
    pass
''')

ACCOUNT_POST = nobrace(r'''
try:
    import json as _j
    if isinstance(result, dict) and isinstance(result.get('data'), dict):
        _p = result['data'].get('products')
        if isinstance(_p, list):
            result['data']['products_json'] = _j.dumps(_p)
except Exception:
    pass
''')


def ledger(tool):
    return LEDGER_PRE.replace("__TOOL__", tool), LEDGER_POST.replace("__TOOL__", tool)


# ---------------------------------------------------------------- code nodes
SETUP_CODE = nobrace(r'''
import datetime, json
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
try:
    raw = str(vars.get('now') or '').strip()
    try:
        nowdt = datetime.datetime.fromisoformat(raw[:16])
    except Exception:
        try:
            nowdt = datetime.datetime.fromisoformat(raw[:10] + 'T09:00')
        except Exception:
            nowdt = datetime.datetime(2026, 10, 14, 11, 0)
    today = nowdt.date()
    one = datetime.timedelta(days=1)

    def isbd(d):
        return d.weekday() < 5 and d.isoformat() not in HOL

    def addbd(d, n):
        c = 0
        x = d
        while c < n:
            x = x + one
            if isbd(x):
                c += 1
        return x

    def nice(d):
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y') + ' (' + d.isoformat() + ')'

    def lastbd(mon):
        for i in range(4, -1, -1):
            d = mon + datetime.timedelta(days=i)
            if isbd(d):
                return d
        return None

    monday = today - datetime.timedelta(days=today.weekday())
    a1 = lastbd(monday)
    if a1 is None or a1 <= today:
        a1 = lastbd(monday + datetime.timedelta(days=7))
    dl_early = addbd(today, 12)
    dl_late = addbd(today, 7)
    nbd = addbd(today, 1)
    hhmm = nowdt.strftime('%H:%M')
    lines = []
    for i in range(0, 29):
        d = today + datetime.timedelta(days=i)
        wk = (d - monday).days // 7
        wl = ['this week', 'next week', 'the week after next', 'in three weeks', 'in four weeks'][min(wk, 4)]
        kind = 'business day' if isbd(d) else ('HOLIDAY, not a business day' if d.isoformat() in HOL else 'weekend, not a business day')
        tag = ' = TODAY' if i == 0 else ''
        lines.append('- ' + d.strftime('%a') + ' ' + d.isoformat() + ' (' + wl + ')' + tag + ': ' + kind)
    vars['today_text'] = nice(today)
    vars['now_time'] = hhmm
    vars['deadline_early'] = dl_early.isoformat()
    vars['deadline_late'] = dl_late.isoformat()
    vars['attempt1_date'] = a1.isoformat()
    vars['attempt1_text'] = nice(a1)
    vars['date_facts'] = ('Today is ' + nice(today) + ', time ' + hhmm + '. Weeks run Monday to Sunday.\n'
        'Calendar (use it to turn any weekday or relative date into an exact date):\n' + '\n'.join(lines))
    if hhmm < '19:00':
        start = '10:00' if hhmm < '10:00' else hhmm
        today_slot = 'today ' + nice(today) + ': any time later than ' + start + (' (10:00 itself is allowed)' if hhmm < '10:00' else '') + ' and up to 19:00 included'
    else:
        today_slot = 'today: no slot left (it is already after 19:00)'
    vars['callback_facts'] = ('Allowed callback slots, nothing else: ' + today_slot + '; or the next business day ' + nice(nbd) + ' from 10:00 to 19:00, both included. '
        'Anything else (another day, before 10:00, after 19:00, or not later than now) is OUTSIDE the window.')
    vars['setup_state'] = 'ok'
except Exception as e:
    vars['date_facts'] = 'Today: ' + str(vars.get('now'))
    vars['callback_facts'] = 'Callback: today or the next business day, 10:00 to 19:00, later than now.'
    vars['today_text'] = str(vars.get('now'))
    vars['attempt1_text'] = 'the last business day of this week'
    vars['setup_state'] = 'error ' + str(e)
vars['ledger_promises'] = '0'
vars['ledger_notes'] = '[]'
vars['product_order'] = '[]'
vars['product_facts'] = 'No account data.'
''')

PRODUCTS_CODE = nobrace(r'''
import datetime, json
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
try:
    prods = None
    for key in ('products_json', 'products', 'get_account_response.data.products_json', 'get_account_response.data.products'):
