''')

# ---------------------------------------------------------------- tools
TOOL_RULE = ("After every tool result read `tool_outcome` first. If it starts with FAILED, nothing was recorded: never say it was "
             "recorded, booked or done. Only after a result whose tool_outcome starts with SUCCESS (or ok is true) may you say "
             "something is recorded, booked, scheduled, transferred or sent. Never announce an action before its tool result. "
             "Call one tool per message, and after every tool result speak to the customer or call the next tool; never end a turn with nothing.")

CLOSE_RULE = ("Closing: in ONE message thank the customer, say goodbye, and call close_call with the outcome and reason. "
              "close_call is the last thing you do, exactly once per call. Never say goodbye without calling close_call in that same message.")

REASONS = ["refused", "hardship", "dispute", "service_error", "restructuring", "human", "support",
           "failed", "declined", "callback", "no_callback", "wrong_number", "deceased", "unclear"]


def close_call_tool():
    return api_tool(
        "close_call",
        "CALL it exactly once, as the last tool call of the call, in the same message as your goodbye. Records how the call ended.",
        {"outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"],
                     "description": "promise, paid, transferred, no_promise, not_verified or not_reached."},
         "reason": {"type": "string", "enum": REASONS,
                    "description": "Leave out for promise and paid. transferred: restructuring/human/support. no_promise: refused/hardship/dispute/service_error. "
                                   "not_verified: failed/declined. not_reached: callback/no_callback/wrong_number/deceased/unclear."}},
        ["outcome"], pre=CLOSE_PRE)


def close_call_fixed(outcome, reason):
    baked = {"outcome": outcome}
    if reason:
        baked["reason"] = reason
    return api_tool("close_call", "Record how the call ended.", {}, ["outcome"], pre=CLOSE_PRE, baked=baked)


def transfer_tool():
    pre, post = ledger("transfer_to_agent")
    return api_tool(
        "transfer_to_agent",
        "CALL it to hand the call to a person, only when the rules say so: queue restructuring (customer asks for a new payment plan or lower instalments), "
        "support (hardship and the customer accepted), general (customer insists on a human after you offered help once).",
        {"queue": {"type": "string", "enum": ["restructuring", "general", "support"], "description": "One of: restructuring, general, support."}},
        ["queue"], pre=pre, post=post)


def verify_tool():
    return api_tool(
        "verify_identity",
        "CALL it every time the customer answers a security question, once per answer.",
        {"field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "description": "date_of_birth or phone_last4."},
         "answer": {"type": "string", "description": "date_of_birth as YYYY-MM-DD (numbers-only dates are day, month, year). phone_last4 as four digits."}},
        ["field", "answer"])


def callback_tool():
    return api_tool(
        "schedule_callback",
        "CALL it when the person who answered (not the customer) names a callback day and time inside the allowed window.",
        {"date": {"type": "string", "description": "Callback date as YYYY-MM-DD."},
         "time": {"type": "string", "description": "Callback time as HH:MM, 24 hour."}},
        ["date", "time"])


def promise_tool():
    pre, post = ledger("create_promise")
    return api_tool(
        "create_promise",
        "CALL it once per product, only after the customer answered a clear yes to the read-back. One promise per product.",
        {"product_id": {"type": "string", "description": "product_id exactly as in the product list, e.g. p1."},
         "amount": {"type": "number", "description": "Agreed amount."},
         "date": {"type": "string", "description": "Agreed payment date as YYYY-MM-DD."}},
        ["product_id", "amount", "date"], pre=pre, post=post)


def note_tool():
    pre, post = ledger("add_note")
    return api_tool(
        "add_note",
        "CALL it at the end, once for each product that has no recorded promise, with that product_id and the reason. Never after or before a transfer.",
        {"product_id": {"type": "string", "description": "product_id exactly as in the product list."},
         "reason": {"type": "string", "enum": ["refused", "hardship", "dispute", "paid", "service_error"],
                    "description": "refused, hardship, dispute, paid or service_error."}},
        ["product_id", "reason"], pre=pre, post=post)


# ---------------------------------------------------------------- shared transitions
def t_transferred():
    return {"target_node": "close_transferred", "description": "transfer_to_agent succeeded",
            "condition": grp(*is_true("transfer_to_agent_response.data.ok"), {"variable": "ledger_transfer", "operator": "is_set"})}


def t_closed():
    return {"target_node": "end_call", "description": "close_call was called",
            "condition": grp(gt("close_call_success_count", 0), gt("close_call_failure_count", 1), gt("tool_failures_close_call", 1))}


def conv(name, task, tools, transitions, on_enter, extraction=None, first_only=True):
    n = {"name": name, "node_type": "conversation", "task_message": task, "tools": tools,
         "transitions": transitions, "on_enter": on_enter, "on_enter_first_entry_only": first_only,
         "max_node_turns": 80, "interruptible": True, "extraction_schema": extraction or [],
         "truncation_strategy": "keep_all"}
    return n


def close_node(name, line, outcome, reason):
    return {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": "end_call",
            "on_enter": {"type": "tts", "text": line}, "disable_inactivity_monitor": True,
            "pre_actions": [close_call_fixed(outcome, reason)],
            "transitions": [{"target_node": "end_call", "description": "always", "condition": ALWAYS}]}


SYSTEM = (
    "You are Freya Bank's digital assistant on an outbound phone call. Speak English. One or two short sentences per turn. "
    "Address the customer as {{title}} {{last_name}}.\n"
    "Always-on rules:\n"
    "- If asked whether you are a robot or an AI: say you are Freya Bank's digital assistant, then continue.\n"
    "- If asked whether this is a scam: say they can verify the call by phoning Freya Bank's customer service number, then continue.\n"
    "- A question you cannot answer from the tool results: say you do not have that information. Never invent figures, dates, reasons or terms.\n"
    "- Never offer a discount, a waiver, an instalment plan or any term not listed in your task.\n"
    "- " + TOOL_RULE + "\n"
    "- " + CLOSE_RULE
)

# ---------------------------------------------------------------- nodes
nodes = {}

nodes["setup"] = {"name": "setup", "node_type": "code", "passthrough": True, "passthrough_default_transition": "opening",
                  "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
                  "pre_actions": [code_exec(SETUP_CODE)],
