"""Generates out/w4-B.workflow.json (Brief A + Brief B, up to three products)."""
import json, pathlib

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1/"
OUT = pathlib.Path(__file__).resolve().parent / "w4-B.workflow.json"


def api_tool(name, desc, fields, required, max_retries=0, pre="", post="", mapping=None, baked=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    for f, spec in fields.items():
        s = dict(spec)
        s.setdefault("default", "{{" + f + "}}")
        props[f] = s
    for f, v in (baked or {}).items():
        props[f] = {"type": "string", "default": v}
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": max_retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + name},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "required": required, "properties": props},
            }},
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


def code_exec(code):
    assert "{{" not in code and "}}" not in code, "braces in code"
    return {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": code},
                "timeout_ms": {"type": "number", "default": 10000}}}}}


def nobrace(code):
    assert "{{" not in code and "}}" not in code, code
    return code


def grp(*conds):
    return {"logic": "or", "conditions": list(conds)}


def eq(var, val):
    return {"variable": var, "operator": "equals", "operand": val}


def gt(var, val):
    return {"variable": var, "operator": "greater_than", "operand": val}


def is_true(var):
    return [eq(var, "true"), eq(var, "True")]


ALWAYS = {"operator": "always"}

