            _sc = int(result.get('status_code') or 0)
        except Exception:
            _sc = 0
        if isinstance(_d, dict) and _d.get('ok') in (True, 'true', 'True') and _sc < 400:
            _ok = True
    if _ok:
        try:
            _p = _j.loads(vars.get('_pending_' + _t) or '[]')
        except Exception:
            _p = dict()
        if not isinstance(_p, dict):
            _p = dict()
        for _k in ('product_id', 'reason', 'queue'):
