        while c < n:
            x = x + one
            if isbd(x):
                c += 1
        return x

    def nice(d):
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y') + ' (' + d.isoformat() + ')'

    def lastbd(mon):
        for i in range(4, -1, -1):
            d = mon + datetime.timedelta(days=i)
            if isbd(d):
                return d
        return None

    monday = today - datetime.timedelta(days=today.weekday())
    a1 = lastbd(monday)
    if a1 is None or a1 <= today:
        a1 = lastbd(monday + datetime.timedelta(days=7))
    dl_early = addbd(today, 12)
    dl_late = addbd(today, 7)
    nbd = addbd(today, 1)
    hhmm = nowdt.strftime('%H:%M')
    lines = []
    for i in range(0, 29):
        d = today + datetime.timedelta(days=i)
