        kind = 'business day' if isbd(d) else ('HOLIDAY, not a business day' if d.isoformat() in HOL else 'weekend, not a business day')
        tag = ' = TODAY' if i == 0 else ''
        lines.append('- ' + d.strftime('%a') + ' ' + d.isoformat() + ' (' + wl + ')' + tag + ': ' + kind)
    vars['today_text'] = nice(today)
    vars['now_time'] = hhmm
    vars['deadline_early'] = dl_early.isoformat()
    vars['deadline_late'] = dl_late.isoformat()
    vars['attempt1_date'] = a1.isoformat()
