    else:
        today_slot = 'today: no slot left (it is already after 19:00)'
    vars['callback_facts'] = ('Allowed callback slots, nothing else: ' + today_slot + '; or the next business day ' + nice(nbd) + ' from 10:00 to 19:00, both included. '
        'Anything else (another day, before 10:00, after 19:00, or not later than now) is OUTSIDE the window.')
    vars['setup_state'] = 'ok'
except Exception as e:
    vars['date_facts'] = 'Today: ' + str(vars.get('now'))
    vars['callback_facts'] = 'Callback: today or the next business day, 10:00 to 19:00, later than now.'
    vars['today_text'] = str(vars.get('now'))
