        if isinstance(v, str) and v.strip().startswith('['):
            try:
                v = json.loads(v)
            except Exception:
                v = None
        if isinstance(v, list) and v:
            prods = v
            break
    if prods is None:
        rebuilt = dict()
        for k, v in list(vars.items()):
            for pre in ('products.', 'get_account_response.data.products.'):
                if str(k).startswith(pre):
                    rest = str(k)[len(pre):].split('.')
                    if len(rest) == 2 and rest[0].isdigit():
                        rebuilt.setdefault(int(rest[0]), dict())[rest[1]] = v
        if rebuilt:
            prods = [rebuilt[i] for i in sorted(rebuilt)]
    raw = str(vars.get('now') or '').strip()
    try:
        today = datetime.date.fromisoformat(raw[:10])
    except Exception:
        today = datetime.date(2026, 10, 14)
    one = datetime.timedelta(days=1)

    def isbd(d):
        return d.weekday() < 5 and d.isoformat() not in HOL

    def addbd(d, n):
        c = 0
        x = d
        while c < n:
            x = x + one
            if isbd(x):
                c += 1
        return x

    def nice(d):
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y') + ' (' + d.isoformat() + ')'

    def money(x):
        try:
            return ('%.2f' % float(x))
        except Exception:
            return str(x)

    a1 = str(vars.get('attempt1_text') or 'the last business day of this week')
    out = []
    order = []
    if not prods:
        raise ValueError('no products')
    for i, p in enumerate(prods):
        pid = str(p.get('product_id'))
        order.append(pid)
        typ = str(p.get('type'))
        if typ == 'credit_card':
            label = 'credit card ending ' + str(p.get('card_last4') or '')
            floor = p.get('minimum_payment')
            floor_name = 'minimum payment'
        elif typ == 'car_loan':
            label = 'car loan'
            floor = p.get('instalment_amount')
            floor_name = 'instalment amount'
        else:
            label = 'personal loan'
            floor = p.get('instalment_amount')
            floor_name = 'instalment amount'
        try:
            dl = int(p.get('days_late'))
        except Exception:
            dl = 0
        if dl <= 7:
            band = 'early'
            dline = addbd(today, 12)
            att = '1 persuasion attempt. Attempt 1: the amount on ' + a1 + '. No attempt 2.'
        else:
            band = 'late'
            dline = addbd(today, 7)
            att = ('2 persuasion attempts. Attempt 1: the amount on ' + a1 + '. Attempt 2: the floor ' + money(floor)
                   + ' on the deadline ' + nice(dline) + '.')
        out.append('PRODUCT ' + str(i + 1) + ': product_id "' + pid + '" (copy exactly). Say it as "' + label + '". '
                   'Past due: ' + money(p.get('past_due')) + '. Days late: ' + str(dl) + ' (' + band + ' band). '
                   'Floor (' + floor_name + '): ' + money(floor) + '. Deadline: ' + nice(dline) + ' (latest promise date for this product). '
                   + att)
    vars['product_facts'] = '\n'.join(out)
    vars['product_order'] = json.dumps(order)
    vars['product_count'] = str(len(order))
    vars['products_ok'] = 'yes'
except Exception as e:
