CLOSE_PRE = nobrace(r'''
try:
    import json as _j
    _b = config.get('body') if isinstance(config, dict) else None
    if isinstance(_b, dict):
        _tq = str(vars.get('ledger_transfer') or '')
        try:
            _pc = int(vars.get('ledger_promises') or 0)
        except Exception:
            _pc = 0
        try:
            _notes = _j.loads(vars.get('ledger_notes') or '[]')
        except Exception:
            _notes = []
        try:
            _order = _j.loads(vars.get('product_order') or '[]')
        except Exception:
            _order = []
        _map = dict(restructuring='restructuring', support='support', general='human')
        if _tq:
            _b['outcome'] = 'transferred'
            _b['reason'] = _map.get(_tq, 'human')
        elif _pc > 0:
            _b['outcome'] = 'promise'
        elif _notes:
            _first = dict()
            for _n in _notes:
                if isinstance(_n, list) and len(_n) == 2 and _n[0] not in _first:
                    _first[_n[0]] = _n[1]
            _rs = [_first[p] for p in _order if p in _first] or list(_first.values())
